// Ranking by squared degrees, corrected for longitude converging towards the
// poles, gets the nearest airport without a trigonometric call per row. The
// winner's real distance is then measured properly, because the threshold has
// to mean metres.
const DEG_TO_M = 111320;

/** Great-circle distance in metres. */
function distanceM(lat1, lon1, lat2, lon2) {
  const R = 6371000;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

// An aircraft further out than this is between airports, not at one. Eight
// kilometres covers the apron and the runway ends of even the largest fields
// in the table while staying well inside the gap to the next airport.
const MAX_DISTANCE_M = 8000;

// Airport names arrive with boilerplate ("Istanbul Sabiha Gökçen International
// Airport") that eats the width of a phone-sized row without adding meaning.
// api/route.js carries its own copy of this rule for adsbdb's names; the two
// sources are unrelated and neither should start deciding for the other.
const NAME_NOISE = /\s*(international|intl\.?|regional|airport|airbase|air base)\b/gi;

function shortName(name) {
  const trimmed = name.replace(NAME_NOISE, '').replace(/\s{2,}/g, ' ').trim();
  // Never shorten a name into nothing — some airports are literally "Airport".
  return trimmed.length >= 3 ? trimmed : name;
}

/**
 * The airport a point is standing on, or null when it is not at one.
 */
export function nearestAirport(lat, lon) {
  const lonScale = Math.cos((lat * Math.PI) / 180);

  let best = null;
  let bestScore = Infinity;

  for (const row of AIRPORTS) {
    const dLat = row[4] - lat;
    const dLon = (row[5] - lon) * lonScale;
    const score = dLat * dLat + dLon * dLon;
    if (score < bestScore) {
      bestScore = score;
      best = row;
    }
  }

  // Cheap reject before measuring: anything this far off in degrees cannot be
  // within the threshold however the approximation erred.
  if (!best || Math.sqrt(bestScore) * DEG_TO_M > MAX_DISTANCE_M * 2) return null;

  const metres = distanceM(lat, lon, best[4], best[5]);
  if (metres > MAX_DISTANCE_M) return null;

  return {
    icao: best[0],
    iata: best[1],
    name: shortName(best[2]),
    city: best[3],
  };
}
